// A received datagram.
type IncomingDatagram struct {
	// The payload.
	//
	// Theoretical max size: ~64 KiB. In practice, typically less than 1500 bytes.
	Data []uint8
	// The source address.
	//
	// This field is guaranteed to match the remote address the stream was initialized with, if any.
	//
	// Equivalent to the `src_addr` out parameter of `recvfrom`.
	RemoteAddress network.IpSocketAddress
}

// A datagram to be sent out.
type OutgoingDatagram struct {
	// The payload.
	Data []uint8
	// The destination address.
	//
	// The requirements on this field depend on how the stream was initialized:
	// - with a remote address: this field must be None or match the stream's remote address exactly.
	// - without a remote address: this field is required.
	//
	// If this value is None, the send operation is equivalent to `send` in POSIX. Otherwise it is equivalent to `sendto`.
	RemoteAddress OptionNetworkIpSocketAddress
}

// TupleIncomingDatagramStreamOutgoingDatagramStream corresponds to a WIT tuple type.
type TupleIncomingDatagramStreamOutgoingDatagramStream struct {
	F0 *IncomingDatagramStreamHandle
	F1 *OutgoingDatagramStreamHandle
}
